import std.io

pub type AppError = Failed(String)

record Log { n: Int64 }

impl Log {
    fn mark(mut self, id: Int64) { self.n = self.n * 10 + id }
}

byres record Handle { log: Log, id: Int64 }

impl Releasable for Handle {
    fn release(mut self) { self.log.mark(self.id) }
}

fn open(log: Log, id: Int64) -> Handle {
    return Handle { log: log, id: id }
}

pub fn main() effect io -> Result<(), AppError> {
    let log = Log { n: 0 }
    scope resource(a = open(log, 1), b = open(log, 2)) {
        io.println("in")
    }
    io.println("${log.n}")
    return Ok(())
}
